<template><view class="page"><text class="brand">安康</text><text class="title">创建账号</text><text class="sub">先完成前端注册流程，数据保存在本地</text><view class="card"><text class="label">手机号</text><input v-model="form.phone" class="input" type="number" maxlength="11" placeholder="请输入手机号"/><text class="label">姓名</text><input v-model="form.name" class="input" maxlength="20" placeholder="请输入姓名"/><text class="label">密码</text><input v-model="form.password" class="input" type="password" placeholder="至少6位"/><text class="label">确认密码</text><input v-model="form.confirmPassword" class="input" type="password" placeholder="再次输入密码"/><text class="label">使用身份</text><view class="roles"><view class="role" :class="{active:form.role==='elder'}" @tap="form.role='elder'">老人</view><view class="role" :class="{active:form.role==='family'}" @tap="form.role='family'">家属</view></view><button class="primary" @tap="submit">注册</button><view class="links"><text @tap="goLogin">已有账号，去登录</text><text @tap="goBack">返回首页</text></view></view></view></template><script>export default{data(){return{form:{phone:'',name:'',password:'',confirmPassword:'',role:'family'}}},methods:{submit(){const f=this.form;if(!/^1\d{10}$/.test(f.phone))return uni.showToast({title:'请输入正确手机号',icon:'none'});if(!f.name.trim())return uni.showToast({title:'请输入姓名',icon:'none'});if(f.password.length<6)return uni.showToast({title:'密码至少6位',icon:'none'});if(f.password!==f.confirmPassword)return uni.showToast({title:'两次密码不一致',icon:'none'});uni.setStorageSync('ankang_demo_user',{phone:f.phone,name:f.name,role:f.role});uni.showToast({title:'注册成功',icon:'success'});setTimeout(()=>uni.reLaunch({url:f.role==='elder'?'/pages/elder/index':'/pages/family/home/index'}),500)},goLogin(){uni.navigateTo({url:'/pages/login/index'})},goBack(){uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/entry/index'})})}}}</script><style scoped>.page{min-height:100vh;padding:110rpx 36rpx 60rpx;background:linear-gradient(180deg,#eef4ec,#fbfaf6);box-sizing:border-box}.brand{display:block;font-size:54rpx;font-weight:900;color:#285b48}.title{display:block;margin-top:18rpx;font-size:42rpx;font-weight:900}.sub{display:block;margin-top:10rpx;color:#758079;font-size:23rpx}.card{margin-top:30rpx;padding:30rpx;background:#fff;border-radius:30rpx}.label{display:block;margin:20rpx 0 10rpx;font-size:22rpx;color:#617168}.input{height:82rpx;padding:0 20rpx;background:#f4f6f3;border-radius:18rpx}.roles{display:flex;gap:16rpx}.role{flex:1;padding:22rpx;text-align:center;background:#f4f6f3;border-radius:18rpx;color:#6d7872}.role.active{background:#dfece4;color:#285b48;font-weight:800}.primary{margin-top:30rpx;background:#315f4b;color:#fff;border-radius:20rpx}.links{display:flex;justify-content:space-between;margin-top:22rpx;font-size:22rpx;color:#597064}</style>